package dev.metallicarts.economy;
import dev.metallicarts.arts.SurvivalCommands;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
/** Finite deliberate inventory transactions. Ratios/acquisition are explicit gameplay policy.
 * Unknown allomantic god-metal/alloy effects are not assigned invented abilities. */
public final class GodmetalCrafting {
 public static void alloy(ServerPlayer p){var held=p.getMainHandItem();var off=p.getOffhandItem();if(!held.is(EconomyContent.ITEMS.get("atium_bead"))||held.getCount()!=1||off.has(dev.metallicarts.registry.ModRegistries.METALMIND)||off.has(dev.metallicarts.registry.ModRegistries.SPIKE))throw new IllegalArgumentException("Hold one pure Atium bead and an ordinary Gold or Electrum ingot offhand");var data=off.get(dev.metallicarts.registry.ModRegistries.METAL_DATA);var composition=off.get(EconomyContent.COMPOSITION);if(data!=null&&Ingestion.invested(data)||composition!=null&&!composition.viable())throw new IllegalArgumentException("Use ordinary viable material");String result;if(off.is(Items.GOLD_INGOT))result="malatium_bead";else if(off.is(EconomyContent.item("electrum","ingot")))result="nalatium_bead";else throw new IllegalArgumentException("Only Gold and Electrum Atium alloys have supported recipes");off.shrink(1);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(EconomyContent.ITEMS.get(result)));}
 public static void split(ServerPlayer p){if(!dev.metallicarts.config.ProgressionConfig.get().lerasiumRecipe())throw new IllegalArgumentException("Host disabled Lerasium acquisition");var held=p.getMainHandItem();var catalyst=p.getOffhandItem();if(held.getCount()!=1||!held.is(EconomyContent.ITEMS.get("harmonium_sample"))||!catalyst.is(EconomyContent.ITEMS.get("trellium_sample"))||SurvivalCommands.count(p,Items.BLAZE_POWDER)<8)throw new IllegalArgumentException("Controlled split needs one Harmonium sample, Trellium catalyst offhand and eight blaze powder");if(p.isInWaterOrRain()||!p.getMainHandItem().is(EconomyContent.ITEMS.get("harmonium_sample"))||!dev.metallicarts.api.ArtsProtection.BLOCK_EVENT.invoker().allow(p,p.blockPosition(),dev.metallicarts.api.ArtsProtection.Action.MOVE_BLOCK))throw new IllegalArgumentException("Use a dry, permitted workstation area");if(!p.level().getBlockState(p.blockPosition().below()).is(EconomyContent.TABLE))throw new IllegalArgumentException("Stand on a Metallurgy Table for the controlled split");if(p.getInventory().getFreeSlot()<0)throw new IllegalArgumentException("Make inventory space before splitting");SurvivalCommands.take(p,Items.BLAZE_POWDER,8);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(EconomyContent.ITEMS.get("atium_bead")));p.getInventory().add(new ItemStack(EconomyContent.ITEMS.get("lerasium_bead")));p.level().playSound(null,p.blockPosition(),net.minecraft.sounds.SoundEvents.FIRE_EXTINGUISH,net.minecraft.sounds.SoundSource.BLOCKS,.5f,.6f);}
 private GodmetalCrafting(){}
}
